// Production Implementation Example for Day 1: How 4 YOE interviews work + roadmap
// Demonstrates best practices, async cancellation token propagation, and error handling:
public async Task ProcessWorkloadAsync(CancellationToken ct = default)
{
    _logger.LogInformation("Starting execution for How 4 YOE interviews work + roadmap");
    await using var scope = _serviceScopeFactory.CreateAsyncScope();
    var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();

    // Execute core logic with resilient error handling:
    var results = await db.Orders
        .AsNoTracking()
        .Where(o => o.IsActive)
        .ToListAsync(ct);

    _logger.LogInformation("Processed {Count} items successfully", results.Count);
}
